def normalize_tags(tags):
    seen = set()
    for tag in tags:
        key = tag.strip().casefold()
        if key not in seen:
            seen.add(key)
            yield tag

def most_common_word(words):
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return max(counts, key=counts.get)

def intersection_labels(first, second):
    second_labels = {label.casefold() for label in second}
    seen = set()
    result = []

    for label in first:
        key = label.casefold()
        if key in second_labels and key not in seen:
            result.append(label)
            seen.add(key)

    return result

def common_suffix(words):
    words = list(words)
    if not words:
        return ""

    suffix = words[0]
    for word in words[1:]:
        length = 0
        limit = min(len(suffix), len(word))
        while length < limit and suffix[-1 - length] == word[-1 - length]:
            length += 1
        suffix = suffix[-length:] if length else ""

    return suffix

def parse_clock(text):
    clock, meridiem = text.strip().split()
    hour_text, minute_text = clock.split(":")

    if len(minute_text) != 2:
        raise ValueError("Minute must be two digits")

    hour = int(hour_text)
    minute = int(minute_text)

    if not 1 <= hour <= 12:
        raise ValueError("Hour must be between 1 and 12")
    if not 0 <= minute <= 59:
        raise ValueError("Minute must be between 00 and 59")
    if meridiem not in ("AM", "PM"):
        raise ValueError("Meridiem must be AM or PM")

    if hour == 12:
        hour = 0
    if meridiem == "PM":
        hour += 12

    return hour * 60 + minute

def sort_events(events):
    from datetime import datetime

    return sorted(events, key=lambda event: datetime.fromisoformat(event["time"]))

def matrix_multiply(left, right):
    if not left:
        return []
    if not right:
        return [[] for _ in left]

    return [
        [
            sum(left_row[k] * right[k][j] for k in range(len(right)))
            for j in range(len(right[0]))
        ]
        for left_row in left
    ]

def count_islands(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    seen = set()
    islands = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 1 or (r, c) in seen:
                continue

            islands += 1
            seen.add((r, c))
            stack = [(r, c)]

            while stack:
                row, col = stack.pop()
                for nr, nc in ((row - 1, col), (row + 1, col),
                               (row, col - 1), (row, col + 1)):
                    if (0 <= nr < rows and 0 <= nc < cols
                            and grid[nr][nc] == 1
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

    return islands
